impl Document {
    pub(crate) fn compare_structured_req(
        &self,
        other: &Document,
        a: &StructuredReq,
        b: &StructuredReq,
        path: &str,
    ) -> Result<(), String> {
        self.compare_traceable(other, a.base(), b.base(), path)?;
        self.compare_variation_point_capable(
            other,
            a.variation_point_capable(),
            b.variation_point_capable(),
            path,
        )?;
        let list_a = a.get_applies_to();
        let list_b = b.get_applies_to();
        if list_a.len() != list_b.len() {
            return Err(format!("{path}: APPLIES_TO length mismatch"));
        }
        for (index, (x, y)) in list_a.iter().zip(list_b.iter()).enumerate() {
            if x != y {
                return Err(format!("{path}.APPLIES_TO[{index}] mismatch"));
            }
        }
        if a.get_conflicts() != b.get_conflicts() {
            return Err(format!("{path}: CONFLICTS mismatch"));
        }
        if a.get_date() != b.get_date() {
            return Err(format!("{path}: DATE mismatch"));
        }
        if a.get_dependencies() != b.get_dependencies() {
            return Err(format!("{path}: DEPENDENCIES mismatch"));
        }
        if a.get_description() != b.get_description() {
            return Err(format!("{path}: DESCRIPTION mismatch"));
        }
        if a.get_importance() != b.get_importance() {
            return Err(format!("{path}: IMPORTANCE mismatch"));
        }
        if a.get_issued_by() != b.get_issued_by() {
            return Err(format!("{path}: ISSUED_BY mismatch"));
        }
        if a.get_rationale() != b.get_rationale() {
            return Err(format!("{path}: RATIONALE mismatch"));
        }
        if a.get_remark() != b.get_remark() {
            return Err(format!("{path}: REMARK mismatch"));
        }
        if a.get_supporting_material() != b.get_supporting_material() {
            return Err(format!("{path}: SUPPORTING_MATERIAL mismatch"));
        }
        let list_a = a.get_tested_item_refs();
        let list_b = b.get_tested_item_refs();
        if list_a.len() != list_b.len() {
            return Err(format!("{path}: TESTED_ITEM_REFS length mismatch"));
        }
        for (index, (x, y)) in list_a.iter().zip(list_b.iter()).enumerate() {
            if x != y {
                return Err(format!("{path}.TESTED_ITEM_REFS[{index}] mismatch"));
            }
        }
        if a.get_type() != b.get_type() {
            return Err(format!("{path}: R#TYPE mismatch"));
        }
        if a.get_use_case() != b.get_use_case() {
            return Err(format!("{path}: USE_CASE mismatch"));
        }
        Ok(())
    }

    pub(crate) fn compare_traceable(
        &self,
        other: &Document,
        a: &Traceable,
        b: &Traceable,
        path: &str,
    ) -> Result<(), String> {
        self.compare_identifiable(other, a.base(), b.base(), path)?;
        let list_a = a.get_trace_refs();
        let list_b = b.get_trace_refs();
        if list_a.len() != list_b.len() {
            return Err(format!("{path}: TRACE_REFS length mismatch"));
        }
        for (index, (x, y)) in list_a.iter().zip(list_b.iter()).enumerate() {
            if x != y {
                return Err(format!("{path}.TRACE_REFS[{index}] mismatch"));
            }
        }
        Ok(())
    }

    pub(crate) fn compare_traceable_table(
        &self,
        other: &Document,
        a: &TraceableTable,
        b: &TraceableTable,
        path: &str,
    ) -> Result<(), String> {
        self.compare_traceable(other, a.base(), b.base(), path)?;
        self.compare_paginateable(other, a.paginateable(), b.paginateable(), path)?;
        if a.get_table() != b.get_table() {
            return Err(format!("{path}: TABLE mismatch"));
        }
        Ok(())
    }

    pub(crate) fn compare_traceable_text(
        &self,
        other: &Document,
        a: &TraceableText,
        b: &TraceableText,
        path: &str,
    ) -> Result<(), String> {
        self.compare_traceable(other, a.base(), b.base(), path)?;
        self.compare_variation_point_capable(
            other,
            a.variation_point_capable(),
            b.variation_point_capable(),
            path,
        )?;
        if a.get_text() != b.get_text() {
            return Err(format!("{path}: TEXT mismatch"));
        }
        Ok(())
    }
}
